export const isContractSignPageResponse = (response) =>
  response.url().includes('/presale/contractMainInfo/page') && response.ok()

export const isContractSignSaveResponse = (response) =>
  response.url().includes('/presale/contractMainInfo/saveContract') && response.request().method() === 'POST'

export const isContractSignDeleteResponse = (response) =>
  response.url().includes('/presale/contractMainInfo/delete') && response.request().method() === 'POST'

export async function gotoContractSignList(page, { cash = false } = {}) {
  const menu = cash ? CONTRACT_SIGN_CASH_MENU : CONTRACT_SIGN_PRE_MENU
  // 棰勫敭鍜岀幇鍞叡鐢?filePath锛屽繀椤讳粠宸叉巿鏉冭彍鍗曢€夋嫨瀵瑰簲璺敱锛屼笉鑳藉湪棰勫敭鍦板潃鍚庢嫾 /cash銆?
  const routes = await collectAppRoutes(page)
  const route = routes.find((item) =>
    item.filePath === menu.filePath &&
    !item.path.includes(':tableid') &&
    (cash ? item.path.endsWith('/cash') : !item.path.endsWith('/cash'))
  )
  expect(route, `褰撳墠璐﹀彿鏈巿鏉?{menu.title}鍒楄〃璺敱`).toBeTruthy()
  await gotoHashPath(page, route.path)
  await dismissErrorDialog(page)
  const testId = cash ? 'contract-sign-cash-list' : 'contract-sign-pre-list'
  await expect(page.getByTestId(testId)).toBeVisible({ timeout: 20000 })
}

export async function toggleContractSignDesensitize(page) {
  const btn = page.getByRole('button', { name: /鏄剧ず|鑴辨晱/ }).first()
  if (await btn.isVisible().catch(() => false)) {
    const listResponse = page.waitForResponse(isContractSignPageResponse, { timeout: 30000 })
