/** 鍒犻櫎鍒楄〃涓鏉″彲鍒犺崏绋匡紙V3锛歅OST /delete 璇锋眰浣撲负瑁?ID 鏁扮粍锛?*/
export async function deleteFirstDeletableContract(page) {
  await gotoContractSignList(page, { cash: false })
  const rows = page.locator('.el-table__body-wrapper tbody tr')
  const rowCount = await rows.count()
  for (let i = 0; i < rowCount; i++) {
    const row = rows.nth(i)
    const deleteBtn = row.getByRole('button', { name: '鍒犻櫎' })
    if (!(await deleteBtn.isVisible().catch(() => false))) continue
    if (await deleteBtn.isDisabled().catch(() => true)) continue
    const contractNo = (await row.locator('td').nth(1).innerText()).trim()
