    expect(Array.isArray(postData), '鍒犻櫎璇锋眰浣撳簲涓鸿８ ID 鏁扮粍').toBe(true)
    expect(postData.length, '鍒犻櫎璇锋眰浣撳簲鑷冲皯鍖呭惈涓€涓?ID').toBeGreaterThan(0)
    const body = await response.json()
    expect(body.code, body.msg || '鍒犻櫎澶辫触').toBe(200)
    await refreshResponse
    if (contractNo) {
      await expect(page.locator('.el-table__body-wrapper tbody tr').filter({ hasText: contractNo })).toHaveCount(0)
    }
    return true
  }
  return false
}
