import { test, expect } from '@playwright/test'
import {
  assertDeveloperCompanyCredentials,
  loginAsDeveloperCompanyOnce
} from '../fixtures/auth-helpers.js'
import {
  gotoContractSignList,
  openChooseHouseDialog
} from '../fixtures/contract-sign-helpers.js'

test.describe.serial('bug6235 新增合同弹窗表格分页/滚动视觉核对', () => {
  test.setTimeout(180000)

  test.beforeAll(() => {
    assertDeveloperCompanyCredentials()
  })

  test.beforeEach(async ({ page }) => {
    await loginAsDeveloperCompanyOnce(page)
  })

  test('户室号分页5条 + 已选房屋固定5条内部滚动', async ({ page }) => {
    await gotoContractSignList(page, { cash: false })
    await openChooseHouseDialog(page)

    const dialog = page.getByRole('dialog', { name: '新增合同' })
    await expect(dialog).toBeVisible()

    // 展开左侧项目 -> 楼幢 -> 单元，加载房屋
    const treeNodes = dialog.locator('.el-tree-node__content')
    // 展开第一个项目节点
    await treeNodes.nth(0).click()
    await page.waitForTimeout(800)
    // 展开第一个楼幢节点
    const node1 = dialog.locator('.el-tree-node__content').filter({ hasNot: dialog.locator('.el-tree-node__expand-icon.is-leaf') })
    await page.waitForTimeout(300)

    // 尝试点击楼幢（第二级）加载房屋
    const buildingNodes = dialog.locator('.el-tree-node__content').nth(1)
    if (await buildingNodes.isVisible().catch(() => false)) {
      await buildingNodes.click()
      await page.waitForTimeout(1500)
    }

    await pause(600)

    // 上面户室号表格
    const originTable = dialog.locator('.choose-house-table-wrap').nth(0).locator('.el-table')
    const targetTable = dialog.locator('.choose-house-table-wrap').nth(1).locator('.el-table')

    // 读取面板是否出现整体滚动条
    const panelScroll = await dialog.locator('.dialog-right-panel').evaluate((el) => ({
      scrollH: el.scrollHeight,
      clientH: el.clientHeight,
      overflowY: getComputedStyle(el).overflowY
    })).catch(() => null)

    // 读取两个表格可见行数
    const measure = async (wrap) => wrap.evaluate((el) => {
      const bodyWrap = el.querySelector('.el-table__body-wrapper')
      const rows = el.querySelectorAll('.el-table__body-wrapper tbody tr')
      return {
        rowCount: rows.length,
        bodyScrollH: bodyWrap ? bodyWrap.scrollHeight : -1,
        bodyClientH: bodyWrap ? bodyWrap.clientHeight : -1,
        hasInnerScroll: bodyWrap ? bodyWrap.scrollHeight > bodyWrap.clientHeight + 1 : false
      }
    })

    const originInfo = await originTable.evaluate((el) => {
      const bodyWrap = el.querySelector('.el-table__body-wrapper')
      return { rows: el.querySelectorAll('.el-table__body-wrapper tbody tr').length,
        innerScroll: bodyWrap ? bodyWrap.scrollHeight > bodyWrap.clientHeight + 1 : false }
    })
    const targetInfo = await targetTable.evaluate((el) => {
      const bodyWrap = el.querySelector('.el-table__body-wrapper')
      return { rows: el.querySelectorAll('.el-table__body-wrapper tbody tr').length,
        innerScroll: bodyWrap ? bodyWrap.scrollHeight > bodyWrap.clientHeight + 1 : false }
    })

    console.log('PANEL', JSON.stringify(panelScroll))
    console.log('ORIGIN', JSON.stringify(originInfo))
    console.log('TARGET', JSON.stringify(targetInfo))

    await page.screenshot({ path: 'test-results/bug6235-dialog.png', fullPage: false })
  })
})

function pause (ms) { return new Promise((r) => setTimeout(r, ms)) }

