export async function loginAsAdmin(page, options = {}) {
  assertAdminCredentials()
  return loginWithRealAccount(page, {
    loginType: 'admin',
    username: options.username ?? getAdminUsername(),
    password: options.password ?? getAdminPassword()
  })
}

/** 涓茶鐢ㄤ緥涓鐢ㄤ富绠￠儴闂ㄧ櫥褰曟€侊紝閬垮厤姣忎釜 test 閲嶅璧板畬鏁寸櫥褰曟祦绋?*/
export async function loginAsAdminOnce(page, options = {}) {
  const hasToken = await page
    .evaluate(() => !!sessionStorage.getItem('Admin-Token'))
    .catch(() => false)
  if (hasToken && !page.url().includes('/login')) {
    await waitForRoutesReady(page)
    await ensureDynamicRoutesRegistered(page)
    return
  }

  if (!cachedAdminStorageState) {
    await loginAsAdmin(page, options)
    cachedAdminAdminToken = await page.evaluate(() => sessionStorage.getItem('Admin-Token'))
    cachedAdminStorageState = await page.context().storageState()
    return
  }

  await page.context().addCookies(cachedAdminStorageState.cookies)
  const origin = cachedAdminStorageState.origins?.[0]
  await page.addInitScript(({ localStorageItems, adminToken }) => {
    for (const { name, value } of localStorageItems || []) {
      localStorage.setItem(name, value)
    }
    localStorage.setItem('driverList', 'true')
    localStorage.setItem('driverDetail', 'true')
    if (adminToken) {
      sessionStorage.setItem('Admin-Token', adminToken)
    }
  }, {
    localStorageItems: origin?.localStorage || [],
    adminToken: cachedAdminAdminToken
  })
  await page.goto(origin?.origin ? `${origin.origin}/#/` : '/#/')
  if (!cachedAdminAdminToken) {
    await hydrateAdminTokenFromCookies(page)
  }
  await waitForRoutesReady(page)
  await ensureDynamicRoutesRegistered(page)
}

export function assertStorageStateForExternalTarget() {
  const storagePath = getStorageStatePath()
  if (!storagePath) {
