        '璇疯繍琛? npm run test:e2e:auth:save',
        `鎴栧湪 e2e/.env.e2e 涓缃?PLAYWRIGHT_STORAGE_STATE锛堥粯璁?e2e/.auth/zsbase.json锛塦
      ].join('\n')
    )
  }
  return storagePath
}

