async function loginWithCredentials(page, { username, password, loginType }) {
  const initialCodePromise = page.waitForResponse((r) => r.url().includes('/code') && r.ok(), { timeout: 30000 })
  await page.goto('/#/login')
  await page.evaluate(() => {
    localStorage.setItem('driverList', 'true')
    localStorage.setItem('driverDetail', 'true')
  })
  await page.waitForSelector('.login-form', { timeout: 30000 })

  let codeRes
  if (loginType === 'company') {
    await page.locator('.login-tabs .el-tabs__item').filter({ hasText: '鏈烘瀯鐧诲綍' }).click()
    codeRes = await page
      .waitForResponse((r) => r.url().includes('/code') && r.ok(), { timeout: 5000 })
      .catch(() => initialCodePromise)
  } else {
    codeRes = await initialCodePromise
  }

  const codeBody = await codeRes.json()
  const captchaPayload = resolveCaptchaFromCodeBody(codeBody)

  const loginBody = await submitLogin(page, {
    username,
    password,
    captcha: captchaPayload.captcha,
    uuid: captchaPayload.uuid,
    loginType
  })

  expect(loginBody.code, `鐧诲綍澶辫触: ${loginBody.msg || loginBody.message}`).toBe(200)
  await page.waitForURL((url) => !url.hash.includes('/login'), { timeout: 30000 })
  await waitForRoutesReady(page)
  return loginBody
}

/**
 * 鐪熷疄璐﹀彿鐧诲綍锛氫笌娉ㄥ唽娴佺▼鍏辩敤 Playwright baseURL锛圗2E_BASE_URL锛夈€?
 * 鏈夎处鍙峰瘑鐮佹椂浼樺厛璧扮櫥褰曢〉鑷姩鐧诲綍锛涙棤鍑嵁涓斿瓨鍦?storageState 鏃跺洖閫€鎵嬪姩淇濆瓨鐨勪細璇濄€?
 */
export async function loginWithRealAccount(page, options = {}) {
  const username = options.username ?? getLoginUsername()
  const password = options.password ?? getLoginPassword()
  const loginType = options.loginType ?? getLoginType()

  if (username && password) {
    return loginWithCredentials(page, { username, password, loginType })
  }

  if (getE2eBaseURL() && getStorageStatePath()) {
    return loginFromStorageState(page)
  }

  assertLoginCredentials()
}

export async function waitForRoutesReady(page, timeout = 45000) {
  await page.waitForFunction(
    () => {
      const app = document.querySelector('#app')?.__vue__
      if (!app?.$store?.getters?.roles?.length) return false

      const permission = app.$store?.state?.permission || {}
      // 浠呬緷鎹潈闄愭ā鍧楀啓鍏ョ殑璺敱琛ㄥ垽鏂氨缁紝閬垮厤 GenerateRoutes 瀹屾垚鍓嶅鑸閲嶅畾鍚戝埌棣栭〉銆?
      return (permission.addRoutes?.length || 0) > 0 || (permission.originalRoutes?.length || 0) > 0
    },
    null,
    { timeout }
  )
  await ensureDynamicRoutesRegistered(page)
}
"}]

