// so we can build a mock route map for offline visual verification.
test('capture api calls', async ({ page }) => {
  page.on('request', (req) => {
    const u = req.url()
    if (u.includes('/api/')) {
      console.log('REQ', req.method(), u.replace('http://127.0.0.1:8098', ''), req.postData() ? 'BODY:' + req.postData().slice(0, 200) : '')
    }
  })
  await page.goto('/#/login')
  await page.waitForTimeout(3000)
  // Failing captcha shows dialog; just record what fired
  await page.screenshot({ path: 'test-results/capture-login.png' })
})

