export function resolveCaptchaFromCodeBody(codeBody) {
  const uuid = codeBody.uuid ?? codeBody.data?.uuid
  const textCaptcha = codeBody.captcha ?? codeBody.data?.captcha
  if (textCaptcha && uuid) {
